<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/config.php';require_once ROOT_PATH.'/database/config/db.php';require_once ROOT_PATH.'/security/middleware/AuthMiddleware.php';require_once ROOT_PATH.'/services/CoworkspaceService.php';AuthMiddleware::startSession();$user=AuthMiddleware::requireAuth(true);header('Content-Type: application/json; charset=utf-8');$db=Database::getInstance();$uid=(int)$user['id'];
function raJson(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function raInput():array{$x=json_decode(file_get_contents('php://input'),true);return is_array($x)?$x:$_POST;}function raPermission(mixed $p):string{$p=strtolower(trim((string)$p));return in_array($p,['view','comment','edit'],true)?$p:'view';}function raResource(PDO $db,int $wid,string $type,int $rid):array{if(!in_array($type,['document','whiteboard'],true)||$rid<1)raJson(['success'=>false,'error'=>'Invalid resource.'],400);$table=$type==='document'?'collab_documents':'collab_whiteboards';$s=$db->prepare("SELECT id,workspace_id,created_by,visibility,public_permission,title FROM {$table} WHERE id=:id AND workspace_id=:wid LIMIT 1");$s->execute([':id'=>$rid,':wid'=>$wid]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)raJson(['success'=>false,'error'=>'Resource not found.'],404);return $r;}
try{$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');$data=$method==='GET'?$_GET:raInput();$wid=(int)($data['workspace_id']??0);$type=strtolower(trim((string)($data['resource_type']??'')));$rid=(int)($data['resource_id']??0);if($wid<1||$rid<1)raJson(['success'=>false,'error'=>'Workspace and resource are required.'],400);$w=CoworkspaceService::get($db,$wid,$uid);$r=raResource($db,$wid,$type,$rid);$owner=(int)$r['created_by']===$uid||(int)($w['host_id']??0)===$uid;if(!$owner)raJson(['success'=>false,'error'=>'Only the resource owner or Coworkspace host can manage access.'],403);
if($method==='GET'){ $s=$db->prepare('SELECT p.user_id,p.permission,p.granted_by,COALESCE(NULLIF(u.full_name,""),u.username,"Unknown") display_name FROM collab_resource_permissions p LEFT JOIN users u ON u.id=p.user_id WHERE p.resource_type=:type AND p.resource_id=:rid AND p.workspace_id=:wid ORDER BY display_name');$s->execute([':type'=>$type,':rid'=>$rid,':wid'=>$wid]);raJson(['success'=>true,'resource'=>$r,'permissions'=>$s->fetchAll(PDO::FETCH_ASSOC)]); }
if($method==='PATCH'||$method==='POST'){AuthMiddleware::verifyCsrf();$visibility=strtolower(trim((string)($data['visibility']??$r['visibility'])));$public=raPermission($data['public_permission']??$r['public_permission']);if(!in_array($visibility,['public','private'],true))raJson(['success'=>false,'error'=>'Visibility must be public or private.'],400);$table=$type==='document'?'collab_documents':'collab_whiteboards';$s=$db->prepare("UPDATE {$table} SET visibility=:visibility,public_permission=:public,updated_by=:uid WHERE id=:id AND workspace_id=:wid");$s->execute([':visibility'=>$visibility,':public'=>$public,':uid'=>$uid,':id'=>$rid,':wid'=>$wid]);raJson(['success'=>true,'visibility'=>$visibility,'public_permission'=>$public]);}
raJson(['success'=>false,'error'=>'Method not allowed.'],405);}catch(Throwable $e){error_log('[collaboration/resource-access] '.$e->getMessage());raJson(['success'=>false,'error'=>'Unable to process access request.'],500);}
